vertex.source:
#version 300 es

// Vertex coordinates in object space for the render quad
in vec3 vertexPosition;
uniform float canvasWidth;
uniform float canvasHeight;
uniform vec3 cameraPosition;
uniform mat3 cameraRotation;
uniform bool isOrthographicProjection;

uniform float orthographicFOV;
uniform float perspectiveFOV;
out vec3 origin;
out vec3 dir;

void main() {
    float aspectRatio = canvasWidth/canvasHeight;
    vec3 origin_camSpace, dir_camSpace;

    if (isOrthographicProjection) {
        origin_camSpace = vec3(vertexPosition.x*orthographicFOV*aspectRatio,vertexPosition.y*orthographicFOV, 0);
        dir_camSpace = vec3(0, 0, -1);
    }
    else {
        // perspective projection
        origin_camSpace = vec3(0);
        dir_camSpace = vec3(vertexPosition.x*aspectRatio,vertexPosition.y, -1.0/tan(radians(perspectiveFOV)));
    }
    origin = cameraPosition + cameraRotation*origin_camSpace;
    dir = normalize(cameraRotation*dir_camSpace);

    gl_Position = vec4(vertexPosition, 1.0);
}

fragment.source:
#version 300 es

precision highp float;

// A texture sampling unit, which is bound to the render quad texture buffer
uniform sampler2D textureRendered;
uniform sampler2D backgroundTexture;
uniform sampler2D floorTexture;
uniform sampler2D floorNormalMap;

// Texture coordinates coming from the vertex shader, interpolated through the rasterizer
in vec2 fragmentTextureCoordinates;
out vec4 fragColor;

// Origin and Direction of Ray from vertex shader
in vec3 origin;
in vec3 dir;

uniform vec3 cameraPosition;
uniform vec3 backgroundColor;
uniform vec3 lightPosition;
uniform float shininess;
uniform float lightIntensity;
uniform bool lightInCamspace;

// Fog variables
uniform float fogPercentage;
uniform vec3 fogColourRGB;

int max_depth = 5;
float epsilon = 0.001;

struct Sphere
{
    vec3 centre;
    float radius;
    vec3 colour;
};

struct Plane
{
    vec3 point;
    vec3 normal;
    vec3 colour;
};

struct Ray
{
    vec3 origin;
    vec3 dir;
};

struct Intersection
{
    vec3 point;
    vec3 normal;
    vec3 ambient;
    vec3 specular;
    vec3 diffuse;
    bool hit;
    bool isMatte; // So it doesn't reflect
};

void localIllumination(inout Intersection intersect,Ray ray,vec3 lightPosition)
{
    vec3 lightDir = normalize(lightPosition.xyz - intersect.point);
    vec3 viewDir = normalize(ray.origin - intersect.point);
    vec3 reflectDir = normalize(reflect(-lightDir, intersect.normal));
    intersect.specular = clamp(pow(max(dot(viewDir, reflectDir), 0.0), shininess)*lightIntensity*intersect.ambient,0.0,1.0);
    intersect.diffuse = clamp(max(dot(intersect.normal, lightDir), 0.0)*lightIntensity*intersect.ambient,0.0,1.0);
}

void localIlluminationTextured(inout Intersection intersect,Ray ray,vec3 lightPosition, sampler2D normalMap)
{
    vec2 texCoords = vec2(intersect.point.x, intersect.point.z);
    vec2 normalisedTexCoords = mod(texCoords, 1.0);

    vec3 normalMapColor = texture(normalMap, normalisedTexCoords).rgb;
    vec3 normal = normalize(normalMapColor * 2.0 - 1.0); 

    vec3 lightDir = normalize(lightPosition.xyz - intersect.point);
    vec3 viewDir = normalize(ray.origin - intersect.point);
    vec3 reflectDir = normalize(reflect(-lightDir, normal));
    intersect.specular = clamp(pow(max(dot(viewDir, reflectDir), 0.0), shininess)*10.0*intersect.ambient,0.0,1.0);
    intersect.diffuse = clamp(max(dot(normal, lightDir), 0.0)*10.0*intersect.ambient,0.0,1.0);
}

Intersection intersectSphere(Ray ray, Sphere sphere) {
    Intersection intersection;
    vec3 deltap=ray.origin-sphere.centre;
    float sqrtterm;
    sqrtterm=pow(dot(ray.dir,deltap),2.0)-pow(length(deltap),2.0)+pow(sphere.radius,2.0);
    float mu1=-dot(ray.dir,deltap)-sqrt(sqrtterm);
    float mu2=-dot(ray.dir,deltap)+sqrt(sqrtterm);
    if (sqrtterm<=0.0 || (mu1<0.0 && mu2<0.0)) {
        intersection.hit=false;
    }
    else {
        intersection.point=ray.origin+min(mu1,mu2)*ray.dir;
        intersection.normal = normalize(intersection.point - sphere.centre);
        intersection.ambient = sphere.colour;
        intersection.hit=true;
        intersection.isMatte = false;
        localIllumination(intersection, ray, lightPosition);
    }
    return intersection;
}

Intersection intersectPlane(Ray ray, Plane plane) {
    Intersection intersect;
    intersect.hit = false;
    float mu= -dot((ray.origin-plane.point),plane.normal)/dot(ray.dir,plane.normal);
    if (mu>=0.0) {
        intersect.hit = true;
        intersect.isMatte = true;
        intersect.point = ray.origin+mu*ray.dir;
        intersect.normal = plane.normal;
        ivec2 textureSize = textureSize(floorTexture,0);
        vec2 texCoords = vec2(intersect.point.x, intersect.point.z);
        vec2 normalisedTexCoords = mod(texCoords, 1.0);
        intersect.ambient = texture(floorTexture, normalisedTexCoords).rgb;
        // intersect.ambient = mod(floor(intersect.point.x*2.0) + floor(intersect.point.z*2.0), 2.0) > 0.0 ? plane.colour : vec3(0.0, 0.0, 0.0);
        localIlluminationTextured(intersect, ray, lightPosition,floorNormalMap);
        // localIllumination(intersect, ray, lightPosition);
    }
    return intersect;
}

Intersection getClosestIntersection(Ray ray, Sphere spheres[6], Plane plane) {
    Intersection allIntersections[7];

    // Intersect all Spheres
    for (int j=0; j < spheres.length(); j++){
        vec3 intersectionPoint;
        vec3 normal;
        allIntersections[j] = intersectSphere(ray, spheres[j]);
    }

    // Intersect all Planes
    allIntersections[6] = intersectPlane(ray, plane);

    // Find the closest Intersection
    Intersection closestIntersection;
    vec3 closestPoint;
    vec3 closestNormal;
    float closestDistance = 1000000.0;
    for (int k = 0; k < allIntersections.length(); k++) {
        if (allIntersections[k].hit) {
            float distance = length(allIntersections[k].point - ray.origin);
            if (distance < closestDistance){
                closestIntersection = allIntersections[k];
                closestDistance = distance;
            }
        }
    }
    return closestIntersection;
}


// Main program for each fragment of the render quad
void main() {
    // START SCENE DEFINITIONS
    Sphere spheres[6];
    spheres[0].centre = vec3(-2.0, 1.5, -3.5);
    spheres[0].radius = 1.5;
    spheres[0].colour = vec3(0.8,0.8,0.8);
    spheres[1].centre = vec3(-0.5, 0.0, -2.0);
    spheres[1].radius = 0.6;
    spheres[1].colour = vec3(0.3,0.8,0.3);
    spheres[2].centre = vec3(1.0, 0.7, -2.2);
    spheres[2].radius = 0.8;
    spheres[2].colour = vec3(0.3,0.8,0.8);
    spheres[3].centre = vec3(0.7, -0.3, -1.2);
    spheres[3].radius = 0.2;
    spheres[3].colour = vec3(0.8,0.8,0.3);
    spheres[4].centre = vec3(-0.7, -0.3, -1.2);
    spheres[4].radius = 0.2;
    spheres[4].colour = vec3(0.8,0.3,0.3);
    spheres[5].centre = vec3(0.2, -0.2, -1.2);
    spheres[5].radius = 0.3;
    spheres[5].colour = vec3(0.8,0.3,0.8);

    // Create floor plane
    Plane plane;
    plane.point = vec3(0.0, -0.5, 0.0);
    plane.normal = vec3(0.0, 1.0, 0.0);
    plane.colour = vec3(0.8,0.8,0.8);
    // END SCENE DEFINITIONS

    // Create ray
    Ray ray;
    ray.origin = origin;
    ray.dir = normalize(dir);
    float k_refl = 1.0;
    vec3 outputColour = vec3(0.0);

    for (int i=0; i<max_depth; i++){
        // Find closest intersection
        vec3 closestPoint;
        vec3 closestNormal;
        // Intersect all objects and get closest Intersection
        Intersection closestIntersection = getClosestIntersection(ray, spheres, plane);
        closestPoint = closestIntersection.point;
        closestNormal = normalize(closestIntersection.normal);

        // If the ray did not intersect with any objects just accumulate the background colour
        // and don't trace again
        if (!closestIntersection.hit){
            // fragColor = vec4(fragColor.rgb + k_refl * texture(backgroundTexture, ray.dir.xy ).rgb, 1.0);
            vec2 texCoords = vec2(1.0-acos(ray.dir.z)/(3.14), atan(ray.dir.y, ray.dir.x)/(3.14));
            vec3 background = texture(backgroundTexture, texCoords).rgb;
            fragColor = vec4(fragColor.rgb + k_refl * background, 1.0);
            return;
        } else{ 
            Ray shadowRay;
            shadowRay.origin = closestPoint + epsilon * closestNormal;
            shadowRay.dir = normalize(lightPosition - closestPoint);
            // Check if the shadow ray intersected with any other object, if so produce shadow at that point
            // Otherwise calculate the correct colour at that point
            Intersection shadowIntersection = getClosestIntersection(shadowRay, spheres, plane);
            if (shadowIntersection.hit) {
                outputColour = vec3(0.0);
            } else {
                outputColour = closestIntersection.ambient * (closestIntersection.diffuse + closestIntersection.specular) * lightIntensity;
            }         
            float distanceToCamera = length(closestPoint - cameraPosition);
            float fogFactor = exp2(-(fogPercentage/100.0) * distanceToCamera * distanceToCamera);
            // Add fog
            outputColour = mix(outputColour, 0.8 * (fogColourRGB/255.0), 1.0 - fogFactor);
            fragColor = vec4(fragColor.rgb + k_refl * outputColour, 1.0);
            // Reduce the reflection factor after each successive reflection to fade the reflections
            k_refl = 0.5 * k_refl;

            // If we want the object to be matte i.e. not reflective - don't cast secondary ray
            if (closestIntersection.isMatte) {
                break;
            }
            // Cast secondary ray and continue to trace it in the next iteration
            ray.origin = closestPoint + epsilon * closestNormal;
            ray.dir = normalize(reflect(ray.dir, closestNormal));
        }
    }
}
